module LocalTimeHelper
  def local_time_tag(timestamp, format:)
    raw_timestamp = if timestamp.respond_to?(:utc)
      timestamp.utc.iso8601(3)
    else
      timestamp.iso8601
    end

    tag.time raw_timestamp,
      datetime: raw_timestamp,
      data: {
        controller: "local-time",
        local_time_format_value: format.to_s
      }
  end
end
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(timestamp, format) {
  const date = parseTimestamp(timestamp)

  if (Number.isNaN(date.getTime())) return timestamp

  switch (format) {
    case "comment":
      return formatCommentTime(date)
    case "auto-close":
      return formatAutoCloseDate(date)
    case "relative":
      return formatRelativeTime(date)
    case "time":
      return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(date)
    case "date":
      return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(date)
    case "weekday-date":
      return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }).format(date)
    case "long-date":
      return new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit", year: "numeric" }).format(date)
    case "date-time":
      return new Intl.DateTimeFormat("en-US", {
        month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
      }).format(date)
    default:
      return new Intl.DateTimeFormat("en-US", { dateStyle: "medium", timeStyle: "short" }).format(date)
  }
}

function parseTimestamp(timestamp) {
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(timestamp)

  if (dateOnly) {
    return new Date(Number(dateOnly[1]), Number(dateOnly[2]) - 1, Number(dateOnly[3]))
  }

  return new Date(timestamp)
}

function formatCommentTime(date) {
  const daysAgo = localDayDifference(date, new Date())

  if (daysAgo === 0) {
    return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(date)
  } else if (daysAgo === 1) {
    return "yesterday"
  } else if (daysAgo > 1 && daysAgo < 7) {
    return `${daysAgo} days ago`
  } else if (daysAgo < 0) {
    return `in ${Math.abs(daysAgo)} days`
  } else {
    return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(date)
  }
}

function formatAutoCloseDate(date) {
  const daysUntil = -localDayDifference(date, new Date())

  if (daysUntil === 0) {
    return "today"
  } else if (daysUntil === 1) {
    return "tomorrow"
  } else if (daysUntil > 1) {
    return `in ${daysUntil} days`
  } else if (daysUntil === -1) {
    return "yesterday"
  } else {
    return `${Math.abs(daysUntil)} days ago`
  }
}

function localDayDifference(fromDate, toDate) {
  const fromDay = Date.UTC(fromDate.getFullYear(), fromDate.getMonth(), fromDate.getDate())
  const toDay = Date.UTC(toDate.getFullYear(), toDate.getMonth(), toDate.getDate())
  return Math.round((toDay - fromDay) / MILLISECONDS_PER_DAY)
}

