path = "app/assets/stylesheets/comments.css"
source = File.read(path)
old = <<~'CSS'
  .comment__permalink-title {
    color: currentColor;
    opacity: 0.66;
    text-decoration: none;
    text-transform: capitalize;
CSS
new = old.sub("text-transform: capitalize;", "text-transform: none;")
abort "comment timestamp style target missing" unless source.include?(old)
File.write(path, source.sub(old, new))
RUBY

